def transform(grid):
    # The separator may be a uniform row or a uniform column.
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            panel = grid[:r]
            break
    else:
        c = next(c for c in range(len(grid[0]))
                 if len({row[c] for row in grid}) == 1)
        panel = [row[:c] for row in grid]
    from collections import Counter
    counts = Counter(x for row in panel for x in row)
    background = counts.most_common(1)[0][0]
    return [[2 if x == background else 3 for x in row] for row in panel]
